 83	    @Transactional
 84	    public Xzz58 createSaleBid(String sellerEmail, Long productSizeId, int bidPrice,
 85	                                 String returnAddress, String postalCode, String receiverPhone
 86	                                , boolean isWarehouseStorage) {
 87	
 88	        Xrd81 seller = userQueryService.findByEmail(sellerEmail);
 89	
 90	
 91	        Xdh20 productSize = productSizeQueryService.findById(productSizeId)
 92	                .orElseThrow(() -> new IllegalArgumentException("해당 상품 사이즈를 찾을 수 없습니다: " + productSizeId));
