 94	
 95	        Xgg74 sale = saleCommandService.createSale(seller, productSize, returnAddress, postalCode, receiverPhone,isWarehouseStorage);
 96	
 97	
 98	        Xzz58 saleBid = Xzz58.builder()
 99	                .seller(seller)
100	                .productSize(productSize)
101	                .bidPrice(bidPrice)
102	                .status(Xtz73Status.PENDING)
103	                .sale(sale)
104	                .build();
105	
106	
107	        saleBid = saleBidRepository.save(saleBid);
108	
109	
110	        sale.assignSaleBid(saleBid);
111	
112	
113	        return saleBid;
114	    }
