122	        Xgg74 sale=saleCommandService.createInstantSale(orderBidId,sellerEmail,returnAddress,postalCode,receiverPhone);
123	
124	        Xzj27 orderBid = orderBidQueryService.findById(orderBidId)
125	                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));
126	
127	
128	
129	        Xzz58 saleBid = Xzz58.builder()
130	                .seller(sale.getSeller())
131	                .productSize(sale.getProductSize())
132	                .bidPrice(orderBid.getBidPrice())
133	                .status(Xtz73Status.MATCHED)
134	                .sale(sale)
135	                .order(orderBid.getOrder())
136	                .build();
137	
138	
139	        saleBid.assignSale(sale);
140	        saleBid.assignOrder(orderBid.getOrder());
141	        sale.assignSaleBid(saleBid);
142	
143	
144	        saleBidRepository.save(saleBid);
145	
146	
147	        return sale.getId();
148	    }
149	
150	    @Transactional
151	    public void deleteSaleBid(Long saleBidId) {
152	
153	        Xzz58 saleBid = saleBidRepository.findById(saleBidId)
154	                .orElseThrow(() -> new IllegalArgumentException("해당 SaleBid를 찾을 수 없습니다: " + saleBidId));
155	
156	
157	        if (saleBid.getOrder() != null) {
158	            throw new IllegalStateException("SaleBid는 Order와 연결되어 있으므로 삭제할 수 없습니다.");
159	        }
160	
161	
162	        if (saleBid.getSale() != null) {
163	            saleCommandService.deleteSale(saleBid.getSale().getId());
164	        }
165	
166	
167	        saleBidRepository.delete(saleBid);
